type StepBaseProps = {
  className?: string;
  state?: "Incomplete" | "Current" | "Completed";
};

export default function StepBase({ className, state = "Incomplete" }: StepBaseProps) {
  const isCompleted = state === "Completed";
  const isCurrent = state === "Current";
  return (
    <div className={className || `content-stretch flex gap-[var(--spacing-lg,12px)] items-start relative ${["Current", "Completed"].includes(state) ? "" : "drop-shadow-[0px_4px_16px_rgba(10,13,18,0.08)]"}`} id={isCompleted ? "node-12029_1441" : isCurrent ? "node-12029_1439" : "node-12029_1437"}>
      <div className={`overflow-clip relative rounded-[var(--radius-full,9999px)] shrink-0 size-[24px] ${isCompleted ? String.raw`bg-[var(--content\/neutral\/white,white)]` : isCurrent ? String.raw`bg-[var(--content\/neutral\/white,white)] shadow-[0px_0px_0px_2px_var(--foreground\/neutral\/white,white),0px_0px_0px_3px_var(--foreground\/fg-brand,#3079ff)]` : String.raw`bg-[var(--bg\/neutral\/white,white)]`}`} id={isCompleted ? "node-12029_1442" : isCurrent ? "node-12029_1440" : "node-12029_1438"} data-name="_Step icon base">
        {["Incomplete", "Current"].includes(state) && (
          <div className={`absolute inset-0 ${isCurrent ? String.raw`bg-[var(--bg\/brand\/strong,#3079ff)] rounded-[var(--spacing-lg,12px)]` : String.raw`bg-[var(--bg\/neutral\/white,white)] rounded-[var(--radius-full,9999px)]`}`} id={isCurrent ? "node-I12029_1440-1139_79867" : "node-I12029_1438-1139_80098"} data-name="Content">
            <div className="-translate-x-1/2 -translate-y-1/2 absolute left-1/2 size-[8px] top-1/2" id={isCurrent ? "node-I12029_1440-1139_79868" : "node-I12029_1438-1139_80099"} data-name="Dot">
              <img alt="" className="absolute block inset-0 max-w-none size-full" src={isCurrent ? imgDot1 : imgDot} />
            </div>
          </div>
        )}
        {isCompleted && <img alt="" className="absolute block inset-0 max-w-none size-full" src={imgStepIconBase} />}
      </div>
    </div>
  );
}
